pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c));

        // lock in the guess at the current block; target block is block.number + 1
        vm.deal(actor, 1 ether);
        vm.startPrank(actor);
        c.lockInGuess(bytes32(0)); // provisional call not needed; we need the real one below
        vm.stopPrank();
        // reset: settle to clear state so we can lock the real hash
        vm.roll(block.number + 1);
        vm.prank(actor);
        c.settle(); // wrong guess (bytes32(0)) -> no payout, state cleared

        // now lock in the hash that matches the answer of the next target block.
        // We record the pre-call block; the stored target becomes recorded + 1.
        uint256 recorded = block.number;
        uint256 target = recorded + 1;
        vm.deal(actor, 1 ether);
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(bytes32(0))));
        // blockhash(target) is deterministic (0 in the EVM for the current/not-yet-mined block),
        // so the correct answer is keccak256(abi.encodePacked(bytes32(0)));
        vm.roll(target + 1);
        c.settle();
        vm.stopPrank();

        // Reference: the stored guess matched, so the prize was paid out -> contract balance drained.
        // Mutant: guess stayed bytes32(0) (never equals keccak256(abi.encodePacked(bytes32(0)))) -> no payout.
        assertTrue(address(c).balance == 0, "winning guess must be honored and prize paid");
    }
}

