pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 hash) public {
        // admissible domain: actor must be an EOA-like caller (no code) so the call completes,
        // the guess hash must be non-zero (zero is where the mutant's stored value coincides),
        // and actor must be fresh so the first require passes.
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.assume(hash != bytes32(0));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Rule: after a successful lockInGuess, the stored guess equals the supplied hash.
        assertTrue(c.guesses(actor).guess == hash);
    }
}

