pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        t = bound(t, 2, type(uint256).max - 1000);

        // Make block t exist so its blockhash is computable.
        vm.roll(t + 1);
        bytes32 ans = keccak256(abi.encodePacked(blockhash(t)));

        // Lock the winning hash so the target block is exactly t.
        vm.roll(t - 1);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(ans);

        // Settle after block t but within 256 blocks of it.
        vm.roll(t + 1);
        vm.prank(actor);
        c.settle();

        // The guess matched the deterministic answer, so the whole prize
        // (initial 1 ether + locked 1 ether) must have been paid out.
        assertTrue(address(c).balance == 0);
    }
}

