pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0) && actor != address(c));

        // player locks in a guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // move past the locked block so settle succeeds
        vm.roll(block.number + 2);

        vm.prank(actor);
        c.settle();

        // Rule: after settling, the player's slot is cleared and they can
        // lock in a new guess. In the mutant the slot is never cleared,
        // so lockInGuess reverts.
        vm.deal(actor, 1 ether);
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(g))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

