pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 blockOffset) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        uint256 lockBlock = block.number;
        blockOffset = bound(blockOffset, 1, 1000000);

        // winning guess: after rolling far beyond the 256-block window,
        // blockhash(target) == 0, so the answer is keccak256(abi.encodePacked(bytes32(0)))
        bytes32 winningGuess = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

        // settle well past the 256-block window so the guessed blockhash is 0
        vm.roll(lockBlock + blockOffset + 300);
        vm.prank(actor);
        c.settle();

        // General rule: a settled winning guess always pays out the 2 ether,
        // leaving the contract with its initial 1 ether only (balance == 0 net of 2 deposited? no: 1 + 1 - 2 = 0).
        assertTrue(address(c).balance == 0 ether, "winning guess must pay out 2 ether");
    }
}

