pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // roll well past the locked block so blockhash(target) == 0 for all inputs
        vm.roll(block.number + 2);

        vm.prank(actor);
        c.settle();

        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));
        bool correct = (guess == answer);

        // Reference rule: balance is 0 iff the guess was correct, 1 ether otherwise.
        assertTrue(correct ? address(c).balance == 0 : address(c).balance == 1 ether);
    }
}
